def default_modes(umask):
    digits = [int(d) for d in f"{umask:03d}"]
    file_mode = "".join(str(6 & ~d & 7) for d in digits)
    dir_mode = "".join(str(7 & ~d & 7) for d in digits)
    return int(file_mode), int(dir_mode)


